import pkg from 'pg';
const { Pool } = pkg;
import dotenv from 'dotenv';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

// Load environment variables from .env and .env.local (generated by Neon)
dotenv.config();
dotenv.config({ path: path.resolve(process.cwd(), '.env.local') });

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);


const isProduction = process.env.NODE_ENV === 'production' || !!process.env.VERCEL;

const poolConfig = process.env.DATABASE_URL
  ? {
      connectionString: process.env.DATABASE_URL,
      ssl: process.env.DATABASE_URL.includes('localhost')
        ? false
        : { rejectUnauthorized: false }
    }
  : {
      host: process.env.PGHOST || 'localhost',
      port: parseInt(process.env.PGPORT || '5432', 10),
      database: process.env.PGDATABASE || 'aurabean_db',
      user: process.env.PGUSER || process.env.USER || 'postgres',
      password: process.env.PGPASSWORD || undefined
    };

export const pool = new Pool(poolConfig);

export async function initDb() {
  try {
    const client = await pool.connect();
    try {
      const schemaPath = path.join(__dirname, 'schema.sql');
      const schemaSql = fs.readFileSync(schemaPath, 'utf8');
      await client.query(schemaSql);
      console.log('✓ PostgreSQL tables verified / initialized successfully.');
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('Error initializing PostgreSQL schema:', err.message);
    throw err;
  }
}
